package com.smartspend.controller;
import com.smartspend.dao.*;import com.smartspend.model.*;import com.smartspend.util.*;import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import java.time.*;
public class BudgetsView extends VBox {private final BudgetDAO dao=new BudgetDAO();private final CategoryDAO cd=new CategoryDAO();private final int uid=Session.getUser().getId();private final VBox list=new VBox(10);public BudgetsView(){setPadding(new Insets(5,30,30,30));setSpacing(15);Button add=UI.button("+ Set Budget");add.setOnAction(e->dialog());getChildren().addAll(UI.title("Budgets"),UI.subtitle("Track monthly limits and receive automatic status alerts."),add,list);load();}private void load(){list.getChildren().clear();for(Budget b:dao.findForMonth(uid,LocalDate.now().getMonthValue(),LocalDate.now().getYear())){double p=b.getPercentage();String status=p>100?"Exceeded":p>=90?"Critical":p>=70?"Warning":"Healthy";ProgressBar bar=new ProgressBar(Math.min(1,p/100));bar.setMaxWidth(Double.MAX_VALUE);Label l=new Label(b.getCategoryName()+"    "+UI.money(b.getSpent())+" / "+UI.money(b.getAmount())+"    "+String.format("%.0f%%",p)+"   "+status);list.getChildren().add(UI.card(l,bar));}}private void dialog(){Dialog<ButtonType>d=new Dialog<>();GridPane g=new GridPane();g.setHgap(10);g.setVgap(10);ComboBox<Category>c=new ComboBox<>();c.getItems().addAll(cd.findAll());TextField amount=UI.input("Monthly limit");g.addRow(0,new Label("Category"),c);g.addRow(1,new Label("Limit"),amount);d.getDialogPane().setContent(g);d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);d.showAndWait().ifPresent(x->{if(x==ButtonType.OK)try{dao.save(new Budget(0,uid,c.getValue().getId(),Double.parseDouble(amount.getText()),LocalDate.now().getMonthValue(),LocalDate.now().getYear(),0,c.getValue().getName()));load();}catch(Exception e){UI.error(getScene().getWindow(),e.getMessage());}});}}
